# Bám sách: trang 74–75 + đáp án + Mini dictionary unit 35. Không chép nguyên văn.
theory = (
 H("A", "Structuring a business", "Cơ cấu doanh nghiệp")
 + P("Short business news items.", "Các mẩu tin kinh doanh ngắn.")
 + T([
    ("<b>head up</b> / <b>look after</b>", "A manager moves to Paris to be in charge of new French operations and will also be responsible for interests in French-speaking Africa.", "Một giám đốc sang Paris phụ trách hoạt động mới ở Pháp và lo cả quyền lợi công ty ở châu Phi nói tiếng Pháp."),
    ("<b>buy out</b>", "Rumours say a phone company plans to buy its rival so it owns all of it.", "Có tin đồn một công ty điện thoại định mua đứt đối thủ."),
    ("<b>set up</b>", "A young pop star has given her parents the money to start the restaurant they wanted.", "Một ngôi sao nhạc pop trẻ đã bỏ tiền giúp bố mẹ mở nhà hàng mơ ước."),
 ])
 + H("B", "Doing business: phrasal verbs and their collocations", "Kinh doanh: phrasal verb và từ đi kèm")
 + table(["Phrasal verb + typical words", "Meaning"], ["Phrasal verb + từ đi kèm", "Nghĩa"], [
    ("<b>aim</b> a product/magazine <b>at</b> women/students", "", "intend it for a particular group", "nhắm tới một nhóm khách"),
    ("<b>break into</b> a new market / the media / Hollywood", "", "get into a field that is hard to enter", "chen chân vào lĩnh vực khó vào"),
    ("<b>bring in</b> customers / clients / new business", "", "attract people to buy", "thu hút khách"),
    ("<b>bring out</b> a new product / a book", "", "produce something for sale", "tung ra sản phẩm"),
    ("<b>deal in</b> art / shares", "", "buy and sell as a business", "buôn bán mặt hàng"),
    ("<b>firm up</b> arrangements / prices / details", "", "make more definite", "chốt cho chắc"),
    ("<b>sign up</b> a new employee / a player / a star", "", "get someone to sign a work contract", "ký hợp đồng tuyển ai"),
    ("<b>turn out</b> cars / films / computers", "", "make or produce for sale", "sản xuất ra"),
    ("<b>turn over</b> $6 million / £100,000", "", "earn an amount in a period", "đạt doanh thu"),
 ])
 + NOTE("<b>Tip</b> (from the book): when you meet a new phrasal verb in business, note it with two or three nouns it collocates with. <b>Key 35.2</b>: with a long object the verb and particle usually stay together (<i>turning out 10,000 pairs of shoes</i>). <b>35.3</b>: <b>set up</b>, <b>break into</b>, <b>bring in</b>, <b>bring out</b>, <b>turn out</b> also have other meanings in other contexts.",
        "<b>Mẹo</b> (của sách): gặp phrasal verb mới trong kinh doanh, hãy ghi kèm hai, ba danh từ đi cùng. <b>Đáp án 35.2</b>: tân ngữ dài thì động từ và tiểu từ thường đi liền (<i>turning out 10,000 pairs of shoes</i>). <b>35.3</b>: <b>set up</b>, <b>break into</b>, <b>bring in</b>, <b>bring out</b>, <b>turn out</b> còn có nghĩa khác trong ngữ cảnh khác.")
)
